INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40228, 0, 0, 0, 0, 0, 0, 0, 0, 'Great work, Ironforge would be proud of the actions you have done this day, please, take these coins, as a token of our gratitude.$B$BPerhaps one day we may resume our work here on a more larger scale!', 0),
(40229, 0, 0, 0, 0, 0, 0, 0, 0, 'Great work, Ironforge would be proud of the actions you have done this day, please, take these coins, as a token of our gratitude.$B$BPerhaps one day we may ressume our work here on a more larger scale!', 0),
(40604, 0, 0, 0, 0, 0, 0, 0, 0, 'Why, you managed to thin their numbers aye?$B$BImpressive work, more then I expected even. Now I can get to work with gathering my report.', 0),
(40605, 0, 0, 0, 0, 0, 0, 0, 0, 'Why, this is the Archive from our digsite in the Badlands, is it not?$B$B<Torwyn lets out a small chuckle of approval.>$B$BBy my beard, we\'ve been looking for this, a chance to log it within our shelves, you\'ve done good work recovering it, you have our gratitude.', 0),
(40648, 0, 0, 0, 0, 0, 0, 0, 0, '<The whelpling flaps its wings excitedly and bounces around.>$B$BHero! Hero $C! You not kill many brood family? No? Only tyrant?', 0),
(40649, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done, I have not expected you back so soon, or back at all in fact.', 0),
(40650, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes, I heard from my scouts the commotion over there. Well done indeed, the Dark Iron Dwarves shall not recover from this wound quickly.', 0),
(40651, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh my word they are heavy! How did you carry them all this way? Well done, well done indeed!', 0),
(40652, 0, 0, 0, 0, 0, 0, 0, 0, 'What beautifully dull looking objects. This is all you found...? Hmm... very well.', 0),
(40653, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, now that is more like it! Did you have to kill... actually, no, let us not discuss that here. Perhaps over an ale later on? Hmm? Or do you prefer rum?', 0),
(40655, 0, 0, 0, 0, 0, 0, 0, 0, 'Hmm, this encampment sounds like it is being built more quickly than I anticipated. Perhaps this is urgent indeed.', 0),
(40656, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent work indeed, $N. I will ensure your name is glorified for your grisly work, here.', 0),
(40657, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, yes, a suitable conclusion to a necessary task.', 0),
(40658, 0, 0, 0, 0, 0, 0, 0, 0, 'Somewhat impressive, though I suppose it speaks of your general demeanor that I was rather expecting failure. Here. Take these coins.', 0),
(40712, 0, 0, 0, 0, 0, 0, 0, 0, 'It may seem cruel of me to ask you to put them to rest, my own people. But fear not stranger, as the sun comes up on the morrow, they too shall rise again.', 0),
(40713, 0, 0, 0, 0, 0, 0, 0, 0, 'The cycle has begone, no doubt you have seen an echo of the past before your eyes, the last king, crowned before the temple.$B$BAn honor to witness one last time.', 0),
(40714, 0, 0, 0, 0, 0, 0, 0, 0, 'Perhaps now you understand it all.', 0),
(40715, 0, 0, 0, 0, 0, 0, 0, 0, 'The Keeper sends our promised salvation. It seems the time has finally come for our curse to be undone.', 0),
(40716, 0, 0, 0, 0, 0, 0, 0, 0, 'I do not know what came to be of the newest generations, but the Keeper once told me that the written word is history\'s greatest triumph and I wish to be remembered.', 0),
(40717, 0, 0, 0, 0, 0, 0, 0, 0, 'The witch is dead, and the curse uplifted. It was by sheer will that I\'ve yet remained to thank you.$B$BI bestow upon you, my crown and blade, may they both serve you well. I will now become an everlasting flame in the lands beyond.', 0),
(70049, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $N. You know I\'ve been thinking about what that dwarf said about ogres pitching tents and it just dawned on me!$B$BI\'m going to make sure there\'s at least one dwarf who can\'t pitch a tent anymore!$B$BAnyways, here is your reward.', 0),
(70050, 0, 0, 0, 0, 0, 0, 0, 0, 'You have no idea how much your help means to me.$B$BHere\'s a little token of my appreciation.', 0),
(80400, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, me bonnie, precious, darling book! What did those scunnered bampots dae to ye?$B$BThank ye, $C, I\'ll never forget yer kindness.$B$BI\'ll be sure to add a dedication to yer name once I put me book back together!', 0),
(40659, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh my, oh my! No, this isn\'t a survival knife, this is a skinning knife. It\'s obvious, see, hold it like this and… there you go. Perfectly crafted that is, not sure I\'ve seen anything like it before. Hold onto it, I suspect it will serve you well.', 0),
(40654, 0, 0, 0, 0, 0, 0, 0, 0, '<His eyes widen and he quickly fishes into his pockets, extending out a handful of golden coins.>$B$BTake them. A good find, a good find indeed.$B$B<He begins to beckon to the surrounding guards. This seems to be an offer you can\'t refuse...>', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40228, 0, 0, 'If there is to ever be peace, then we must act with swiftness.', 0),
(40229, 0, 0, 'They are incredibly stubborn, and will not give up without a fight.', 0),
(40604, 0, 0, 'Any progress with those troggs?', 0),
(40605, 0, 0, 'Can I help you with anything $C?', 0),
(40648, 0, 0, '<It lets out a distressed mewling.>', 0),
(40649, 0, 0, 'Have you made any progress, $R?', 0),
(40650, 0, 0, 'Is it done? Is he dead? Or must I find someone more competent to carry out the task?', 0),
(40651, 0, 0, 'Have you had any success? I can\'t wait to tinker with those hearts!', 0),
(40652, 0, 0, 'How goes the search, $N?', 0),
(40653, 0, 0, '<He barely looks at you as you approach.>', 0),
(40655, 0, 0, 'Has the camp been torn apart yet?', 0),
(40656, 0, 0, 'Yes?', 0),
(40657, 0, 0, 'Make it quick.', 0),
(40658, 0, 0, 'This had better be good news, or I\'m calling the guards.', 0),
(40712, 0, 0, 'Do not pity them.', 0),
(40713, 0, 0, 'It is only a matter of time now.', 0),
(40714, 0, 0, '<The Forgotten Keeper stares at you.>', 0),
(40715, 0, 0, 'Hail.', 0),
(40716, 0, 0, '<Corthan stares at the parchment you have in your hand.>', 0),
(40717, 0, 0, 'This day has come.', 0),
(70049, 0, 0, 'Any luck finding that cloth I need?', 0),
(70050, 0, 0, 'That drunk old dwarf. Ugh! Please come back as soon as you can.', 0),
(80400, 1, 0, 'Wreckin\' me camp, stealin\' me belongings, eatin\' me haggis and even settin\' me camp ablaze are nowhere near as horrible a crime as stealin\' me bonnie book!$B$BMake \'em suffer worse than a gryphon with clipped wings!', 0),
(40659, 0, 0, 'Hail, adventurer! I see you are a capable... hmm? What do you want?', 0),
(40654, 0, 0, 'Hmm? What are you coming to me with this time, $N?', 0);
