INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61066, 0, 0, 'Your armies have been defeated, and now you stand before the King of Corthan, if you desire to save the lives of the survivors, and yourself, you must swear loyalty to me, as King.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66526'),
(61068, 0, 0, 'I swear my fealty to you, King of Corthan.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66527'),
(61067, 0, 0, 'I will remain loyal.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66528');
